SELECT et.id, et.emp_id AS empId, et.emp_name AS empName, et.emp_team AS empTeam, ar.state AS attendanceState, et.task_type AS taskType, sn_code1 AS snCode1, sn_code2 AS snCode2, sn_code3 AS snCode3, sn_code4 AS snCode4, sn_code5 AS snCode5, sn_code6 AS snCode6, sn_code7 AS snCode7, sn_code8 AS snCode8, sn_code9 AS snCode9, sn_code10 AS snCode10, sn_code11 AS snCode11, sn_code12 AS snCode12, sn_code13 AS snCode13, sn_code14 AS snCode14, sn_code15 AS snCode15, sn_code16 AS snCode16, sn_code17 AS snCode17, sn_code18 AS snCode18, sn_code19 AS snCode19, sn_code20 AS snCode20, et.create_time AS createTime, et.update_time AS updateTime FROM fqc_employee_task et LEFT JOIN fqc_attendance_record ar ON et.emp_id = ar.emp_id
et.is_deleted = 0
AND DATE(et.create_time) = CURDATE()
AND emp_id = #{queryParams.empId}
AND emp_name LIKE CONCAT('%', #{queryParams.empName}, '%')
AND task_type = #{queryParams.taskType}
AND ( sn_code1 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code2 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code3 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code4 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code5 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code6 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code7 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code8 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code9 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code10 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code11 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code12 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code13 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code14 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code15 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code16 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code17 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code18 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code19 LIKE CONCAT('%', #{queryParams.snCode}, '%') OR sn_code20 LIKE CONCAT('%', #{queryParams.snCode}, '%') )
AND emp_team = #{queryParams.empTeam}
ORDER BY updateTime DESC, task_type ASC
